const updateUser = `-- name: UpdateUser :execrows
UPDATE users
SET
    first_name = $1,
    last_name = $2,
    email = $3,
    phone = $4,
    prefecture_id = $5,
    city = $6,
    street = $7,
    building = $8,
    postal_code = $9,
    updated_at = $10,
    deleted_at = $11
WHERE id = $12
    AND deleted_at IS NULL
`

type UpdateUserParams struct {
	FirstName    string
	LastName     string
	Email        string
	Phone        string
	PrefectureID uuid.UUID
	City         string
	Street       string
	Building     *string
	PostalCode   string
	UpdatedAt    time.Time
	DeletedAt    *time.Time
	ID           uuid.UUID
}

// === source: database/dml/repository/user/update_user.sql ===
//
//	UPDATE users
//	SET
//	    first_name = $1,
//	    last_name = $2,
//	    email = $3,
//	    phone = $4,
//	    prefecture_id = $5,
//	    city = $6,
//	    street = $7,
//	    building = $8,
//	    postal_code = $9,
//	    updated_at = $10,
//	    deleted_at = $11
//	WHERE id = $12
//	    AND deleted_at IS NULL
func (q *Queries) UpdateUser(ctx context.Context, arg *UpdateUserParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateUser,
		arg.FirstName,
		arg.LastName,
		arg.Email,
		arg.Phone,
		arg.PrefectureID,
		arg.City,
		arg.Street,
		arg.Building,
		arg.PostalCode,
		arg.UpdatedAt,
		arg.DeletedAt,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
